#define CLOCK_TLS_MIN_EPOCH        ((time_t)1704067200) /* 2024-01-01 00:00 UTC */
#define CLOCK_TLS_PLACEHOLDER_EPOCH ((time_t)1772275200) /* 2026-02-28 00:00 UTC */

