input.new_string:
/****************************************************************************
 * 开机自检 —— 把「这块板子现在能不能开工」写在字幕板上
 *
 * 字幕板本来就是给旁边大人看的（不是给小孩的），上台前扫一眼就知道该不该开始，
 * 而不用等小孩说完一句话才发现它没反应。
 *
 * 判据只用两个现成的非阻塞标志位，不新增任何网络请求、不碰任何控制流：
 *
 *   network_is_connected()      拿到 IP 没有
 *   agent_clock_is_verified()   时钟校过没有
 *
 * 第二条是重点。这块板子没有 RTC，时钟不对的话 HTTPS 证书的 notBefore 校验会
 * 全部失败，云端 ASR / LLM / TTS 一起哑掉 —— 而表面上一点异常都没有，脸照常
 * 动、字幕照常空着，看起来就像「它不想理你」。这是最难在现场查的一类故障，
 * 所以宁可开机就写在脸上。
 *
 * 网络是慢慢起来的（WiFi 关联要十几秒），所以每秒看一次、**结论变了才写字幕**，
 * 免得开机那一瞬间的「还没联网」把人吓一跳。一旦测出「可以开始」就收工，
 * 之后演示过程中不再干扰字幕板。
 ****************************************************************************/

static int  g_selfcheck_state = -1;  /* -1 没测过；0 没网；1 没校时；2 就绪 */
static bool g_selfcheck_done  = false;

/* 返回 true = 已经全好，调用方可以把这个定时器删掉了 */
static bool boot_selfcheck(void)
{
    char line[80];
    bool net = network_is_connected();
    bool clk = agent_clock_is_verified();
    int  state;

    if (!net)
      {
        state = 0;
        snprintf(line, sizeof(line), "自检：还没联网，只能看到脸");
      }
    else if (!clk)
      {
        state = 1;
        snprintf(line, sizeof(line), "自检：网络通了，但时间没校上");
      }
    else
      {
        state = 2;
        snprintf(line, sizeof(line), "自检：网络通、已校时，可以开始");
      }

    if (state == g_selfcheck_state)
      {
        return state == 2;
      }

    g_selfcheck_state = state;

    syslog(LOG_INFO, "[kid_buddy] selfcheck: net=%d clock=%d -> %s\n",
           (int)net, (int)clk, line);

    /* 正在说话或正在回复时别抢字幕板 —— 那上面的字是给小孩看的上下文 */
    if (!g_reply_busy && !g_obs_speaking)
      {
        face_text_reply(line, true);
      }

    return state == 2;
}

static void selfcheck_timer_cb(lv_timer_t *timer)
{
    if (g_selfcheck_done)
      {
        lv_timer_delete(timer);
        return;
      }

    if (boot_selfcheck())
      {
        /* 就绪了。留最后那行字在屏幕上，然后不再管字幕板。 */
        g_selfcheck_done = true;
        lv_timer_delete(timer);
      }
}

