482	{
483	    if (!s_running) {
484	        return;
485	    }
486	
487	    s_running = false;
488	
489	    /* Close socket first to unblock any blocking recv in sync thread */
490	    if (s_sockfd >= 0) {
491	        close(s_sockfd);
492	        s_sockfd = -1;
493	    }
