495	    /* Wait for the sync thread to actually exit before returning. Without
496	     * this, a fast stop→start (e.g. `set_mqtt`) leaves the old thread alive:
497	     * start() flips s_running back to true and creates a second thread, and
498	     * the two threads CONNECT with the same client_id → the broker keeps
499	     * kicking one off → endless reconnect loop (MQTT_ERROR_SOCKET_ERROR). */
500	    for (int i = 0; i < 20 && !s_sync_thread_exited; i++) {
501	        usleep(100 * 1000);
502	    }
