 * 板子每 200ms 发一片，这里按 seq/total 拼回去再解析。 */

var storyBuf = null;   /* 正在收的一批：{total, target, parts, got} */

function syncStories(){
  if (!connected) { log('未连接，先连上 broker 再同步', 'sys'); return; }
  storyBuf = null;                       /* 丢掉上一次没收完的残片 */
  $('storyInfo').textContent = '同步中…';
  publish({ type: 'history', target: STORY_TARGET,
            chat_id: $('chatId').value.trim() || 'parent' },
          '→ 请求孩子的冒险记录');
