function onStoryChunk(o){
  var total = o.total | 0, seq = o.seq | 0;
  if (total < 1 || seq < 1 || seq > total) return;

  /* total 变了说明板子开了新的一批，重新开始收 */
  if (!storyBuf || storyBuf.total !== total || storyBuf.target !== o.target) {
    storyBuf = { total: total, target: o.target,
                 parts: new Array(total), got: 0 };
  }

  if (storyBuf.parts[seq - 1] === undefined) {
    storyBuf.parts[seq - 1] = o.data || '';
    storyBuf.got++;
  }
  $('storyInfo').textContent = '收到 ' + storyBuf.got + '/' + total + ' 片';

  if (storyBuf.got === total) {
    var b64 = storyBuf.parts.join('');
    var target = storyBuf.target;
    storyBuf = null;
    importStoryJson(b64ToUtf8(b64), target);
  }
}

function b64ToUtf8(b64){
  var bin = atob(b64), i;
  var bytes = new Uint8Array(bin.length);
  for (i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}

function importStoryJson(json, target){
  var arr;
  try { arr = JSON.parse(json); } catch(e){
    $('storyInfo').textContent = '解析失败';
    log('故事记录解析失败：' + e, 'sys');
    return;
  }
  if (!Array.isArray(arr)) arr = [];

  dbOpen(function(d){
    if (!d) { $('storyInfo').textContent = '本机存储不可用'; return; }
    var tx = d.transaction(STORY_STORE, 'readwrite');
    var os = tx.objectStore(STORY_STORE);

    arr.forEach(function(m){
      if (!m || typeof m.content !== 'string' || !m.content) return;
      os.put({                        /* key 一样 = 覆盖，天然去重 */
        key:     storyKey(m),
        role:    m.role || 'assistant',
        content: m.content,
        ts:      (typeof m.ts === 'number') ? m.ts : 0,
        target:  target
      });
    });

    tx.oncomplete = function(){ renderStories(); };
    tx.onerror    = function(){ $('storyInfo').textContent = '写入失败'; };
  });
