 * 板子写进会话文件的 ts 是那一轮的时间戳（秒），同一条消息每次同步都一模一样，
 * 所以重复同步能精确命中同一把键。哈希只用来把长内容压短，不用来防碰撞攻击。 */
function storyKey(m){
  var s = (m.role || '') + '|' + (m.ts || 0) + '|' + (m.content || '');
  var h = 5381, i;
  for (i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return (m.ts || 0) + '-' + (h >>> 0).toString(36);
}

function renderStories(){
  dbOpen(function(d){
    if (!d) return;
    var rows = [];
    var tx = d.transaction(STORY_STORE, 'readonly');
    tx.objectStore(STORY_STORE).openCursor().onsuccess = function(e){
      var c = e.target.result;
      if (!c) { drawStories(rows); return; }
      rows.push(c.value);
      c.continue();
    };
  });
}

function drawStories(rows){
  var el = $('storyList');

  if (!rows.length) {
    el.innerHTML = '<div class="story-empty">还没有记录。孩子在板子上开始一段冒险之后，' +
                   '点上面的「同步」就会取过来，存在这台手机上。</div>';
    $('storyInfo').textContent = '';
    return;
  }

  rows.sort(function(a, b){ return (a.ts || 0) - (b.ts || 0); });

  /* 一次冒险 = 一组时间挨得近的往来。板子不告诉我们会话边界，
   * 按间隔 30 分钟切分 —— 孩子中间跑去吃饭再回来，算新的一段。 */
  var groups = [], cur = null;
  rows.forEach(function(r){
    if (!cur || ((r.ts || 0) - cur.end) > 1800) {
      cur = { start: r.ts || 0, end: r.ts || 0, items: [] };
      groups.push(cur);
    }
    cur.items.push(r);
    if ((r.ts || 0) > cur.end) cur.end = r.ts || 0;
  });

  var html = '';
  for (var i = groups.length - 1; i >= 0; i--) {   /* 新的排最前 */
