  el.scrollTop = 0;
  $('storyInfo').textContent = '本机共 ' + rows.length + ' 条';
}

function escHtml(s){
  return String(s).replace(/[&<>"]/g, function(c){
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
  });
}

function fmtWhen(ts){
