/* ⚠️ 千万别把各片的 base64 字符串直接拼起来再解码 —— 那是错的。
 *
 * 每片的字节数不一定能整除 3，base64 编码后末尾会带 '=' 填充；把几个带填充的
 * base64 串首尾相接，解码出来是错位的乱码（实测：3621 字节的历史拼回来只剩
 * 767 字节，只活下来最后一片）。
 *
 * 正确做法是**每片各自解码成字节，再把字节拼起来**，最后整体做一次 UTF-8
 * 解码。这样片与片之间哪怕正好切断一个汉字也没关系 —— 字节流拼回去就复原了。 */
function partsToUtf8(parts){
  var bufs = [], total = 0, i, j, bin, u8;

  for (i = 0; i < parts.length; i++) {
    bin = atob(parts[i] || '');
    u8 = new Uint8Array(bin.length);
    for (j = 0; j < bin.length; j++) u8[j] = bin.charCodeAt(j);
    bufs.push(u8);
    total += u8.length;
  }

  var all = new Uint8Array(total), off = 0;
  for (i = 0; i < bufs.length; i++) {
    all.set(bufs[i], off);
    off += bufs[i].length;
  }

  return new TextDecoder('utf-8').decode(all);
}

