#define MQTT_NOTE_MAX 180   /* 留言正文上限（cron_job_t.message 是 256，
                               要留出「妈妈给你留了句话：」的余地） */

static void mqtt_note_handle(const char *to, const char *from,
                             const char *content, long delay_s)
{
    cron_job_t job;
    memset(&job, 0, sizeof(job));

    if (content == NULL || content[0] == '\0') return;

    const char *who = (from && from[0]) ? from : "爸爸妈妈";

    /* message 字段 256 字节，超了会被 cron 那边截断，所以这里先自己截。 */
    if (strlen(content) > MQTT_NOTE_MAX) {
        syslog(LOG_WARNING, "[%s] note: 内容 %u 字节，截到 %d\n",
               TAG, (unsigned)strlen(content), MQTT_NOTE_MAX);
    }

    snprintf(job.name, sizeof(job.name), "家长留言");
    snprintf(job.message, sizeof(job.message), "%s给你留了句话：%.*s",
             who, MQTT_NOTE_MAX, content);

    job.kind = CRON_KIND_AT;
    job.at_epoch = (int64_t)time(NULL) + (delay_s > 0 ? delay_s : 1);
    job.delete_after_run = true;
    job.enabled = true;

    /* 交给 kid_buddy 去念 —— 和远端提醒走同一条路 */
    strncpy(job.channel, AGENT_CHAN_LOCAL_CLIENT, sizeof(job.channel) - 1);
    strncpy(job.chat_id, "kid_buddy", sizeof(job.chat_id) - 1);

    /* 孩子确认后回执给家长 */
    strncpy(job.report_channel, AGENT_CHAN_MQTT, sizeof(job.report_channel) - 1);
    strncpy(job.report_chat_id, to, sizeof(job.report_chat_id) - 1);

    if (cron_add_job(&job) != OK) {
        mqtt_channel_send(to, "留言没排上（板子上的定时任务满了），过会儿再试试。");
        return;
    }

    syslog(LOG_INFO, "[%s] note: %lds 后念「%s」给 %s\n",
           TAG, delay_s, job.message, job.chat_id);

    /* 回一条确认给家长 */
    {
        char ack[160];
        if (delay_s >= 3600)
            snprintf(ack, sizeof(ack), "留言收到，%.1f 小时后念给孩子。", delay_s / 3600.0);
        else if (delay_s >= 60)
            snprintf(ack, sizeof(ack), "留言收到，%ld 分钟后念给孩子。", delay_s / 60);
        else if (delay_s > 0)
            snprintf(ack, sizeof(ack), "留言收到，%ld 秒后念给孩子。", delay_s);
        else
            snprintf(ack, sizeof(ack), "留言收到，马上就念给孩子。");

        mqtt_channel_send(to, ack);
    }
}
