/* ── 给孩子留句话 ────────────────────────────────────────────
 *
 * 板子收到的是一句话 + 一个「多少秒之后」，会排成定时任务，到点用 TTS
 * 念给孩子 —— **原话不改写**（板子那边走的是不含大模型的那条路，
 * 所以不会像普通提问那样被模型重写一遍）。
 * 孩子听完说「知道了」时，回执会发回这台手机。
 *
 * 为什么只发「多少秒之后」而不是一个钟点：板子没有 RTC，时钟可能还没校准。
 * 发时长的话，钟走得再偏，走一秒还是一秒，到点一定准。 */

function sendNote(){
  var t = $('noteText').value.trim();

  if (!t) { noteStatus('写点什么再发吧'); return; }
  if (!connected) { noteStatus('未连接，先连上 broker'); return; }

  var d = noteDelaySeconds();

  publish({ type: 'note', content: t,
            from: $('noteFrom').value.trim() || '爸爸妈妈',
            delay: d,
            chat_id: $('chatId').value.trim() || 'parent' },
          '→ 给孩子留言：' + t);

  $('noteText').value = '';
  noteStatus('已发出，' + fmtDelay(d) + '后念给孩子');
}

/* 「今晚 20:00」这种按本机时间换算成秒数 —— 换算用手机的时间，
 * 但计时是板子自己的事 */
function noteDelaySeconds(){
  var v = $('noteWhen').value;
  if (v === 'bedtime20') return secsUntil(20, 0, false);
  if (v === 'morning7')  return secsUntil(7, 0, true);
  return parseInt(v, 10) || 0;
}

function secsUntil(hh, mm, forceNextDay){
  var now = new Date();
  var t = new Date(now.getFullYear(), now.getMonth(), now.getDate(),
                   hh, mm, 0, 0);
  /* 今天这个点已经过了就顺延到明天 */
  if (forceNextDay || t.getTime() <= now.getTime()) {
    t.setDate(t.getDate() + 1);
  }
  return Math.max(0, Math.round((t.getTime() - now.getTime()) / 1000));
}

function fmtDelay(d){
  if (d <= 0) return '马上';
  if (d >= 3600) return (Math.round(d / 360) / 10) + ' 小时';
  if (d >= 60) return Math.round(d / 60) + ' 分钟';
  return d + ' 秒';
}

