/* 尾部语气词，从后往前一层层剥 */
static const char *const g_petname_particles[] = {
    "好不好", "好吗", "可以吗", "吧", "呀", "啊", "哦", "呢",
    "嘛", "了", "哟", "噢", "哈", "呗",
};
#define PETNAME_PARTICLE_COUNT \
    (sizeof(g_petname_particles) / sizeof(g_petname_particles[0]))

static void petname_persist(void)
{
    FILE *f = fopen(PETNAME_PATH, "w");

    if (f == NULL)
      {
        return;   /* 写不进去只丢跨重启的记忆，当前这轮不受影响 */
      }

    fputs(g_pet_name, f);
