 * 像一台机器。「它会累、它会睡」这件事本身就是陪伴的一部分。
 *
 * ⚠️ 时间判定**必须先看时钟可不可信**（agent_clock_is_verified）——
 * 这块板子没有 RTC，开机时系统时间是 1970；不看这个标志的话，
 * 它会在大白天睡觉、半夜精神抖擞。
 */

static void sleep_persist(void)
{
    FILE *f = fopen(SLEEP_PATH, "w");

    if (f == NULL)
      {
        return;
      }

    fprintf(f, "%d %d\n", g_sleep_from, g_sleep_to);
    fclose(f);
}

static void sleep_load(void)
{
    FILE *f = fopen(SLEEP_PATH, "r");
    int   from;
    int   to;

    if (f == NULL)
      {
        return;    /* 没有文件就用默认值 21 → 7 */
      }

    if (fscanf(f, "%d %d", &from, &to) == 2
        && from >= 0 && from <= 23 && to >= 0 && to <= 23)
      {
        g_sleep_from = from;
        g_sleep_to   = to;
        syslog(LOG_INFO, "[kid_buddy] 睡觉时间：%02d:00 → %02d:00%s\n",
               from, to, (from == to) ? "（已关闭）" : "");
      }

    fclose(f);
}

static void sleep_set(int from, int to)
{
    if (from < 0 || from > 23 || to < 0 || to > 23)
      {
        syslog(LOG_WARNING, "[kid_buddy] sleep: 钟点不合法（%d %d），忽略\n",
               from, to);
        return;
      }

    g_sleep_from = from;
    g_sleep_to   = to;
    sleep_persist();

    syslog(LOG_INFO, "[kid_buddy] 睡觉时间改为：%02d:00 → %02d:00%s\n",
           from, to, (from == to) ? "（已关闭）" : "");
}

/* 现在是不是睡觉时间？ */
static bool bedtime_now(void)
{
    time_t    now;
    struct tm tm;

    if (g_sleep_from == g_sleep_to)
      {
        return false;              /* 起止相同 = 这个功能关着 */
      }

    /* 时钟不可信就不判 —— 宁可它醒着，也不能让它在错误的钟点上睡觉 */
    if (!agent_clock_is_verified())
      {
        return false;
      }

    now = time(NULL);

    if (localtime_r(&now, &tm) == NULL)
      {
        return false;
      }

    if (g_sleep_from < g_sleep_to)
      {
        /* 同一天之内，比如 13 → 15 */
        return tm.tm_hour >= g_sleep_from && tm.tm_hour < g_sleep_to;
      }

    /* 跨午夜，比如 21 → 7 */
    return tm.tm_hour >= g_sleep_from || tm.tm_hour < g_sleep_to;
}

